static u8 title_block(u8 id, u8 part) {
    const u8 *m = title_meta + (u16)id * 5;
    u8 w = m[3], h = m[4];
    u8 r0 = (u8)(part * 4), r1 = (u8)(r0 + 4);
    const u8 *t, *a;
    if (r1 > h) r1 = h;
    t = title_bt[id] + (u16)r0 * w;
    a = title_ba[id] + (u16)r0 * w;
    if (m[0]) {
        set_win_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), t);
        VBK_REG = 1;
        set_win_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), a);
    } else {
        set_bkg_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), t);
        VBK_REG = 1;
        set_bkg_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), a);
    }
    VBK_REG = 0;
    return r1 < h ? 1 : 0;
}

u8 intro_io_title(u8 op, u8 a, u8 b) BANKED {
    switch (op) {
    case IOP_LOAD:
        if (a < 1u) {
            u16 first = (u16)a << 5;
            u8 cnt = (23u - first) > 32 ? 32 : (u8)(23u - first);
            VBK_REG = (u8)(first >> 8);
            set_bkg_data((u8)first, cnt, title_tiles + (first << 4));
            VBK_REG = 0;
            return 1;
        }
        if ((u8)(a - 1u) < 5u) {
            title_block(0, (u8)(a - 1u));
            return 1;
        }
        memcpy(intro_pal, title_pals, 64);
        return 0;
    case IOP_BLOCK:
        return title_block(a, b);
    case IOP_PAL:
        memcpy(intro_pal, title_pals + (u16)a * 32, 64);
        return 0;
    }
    return 0;
}
